rules.logic:
if (element.querySelector('.recommended-self-help-block')) return;

var block = document.createElement('div');
block.className = 'recommended-self-help-block';
block.style.cssText = 'margin-top:16px;padding:16px;background:#f0f0f5;border-radius:8px;border-left:4px solid #520044;';

var heading = document.createElement('h2');
heading.style.cssText = 'margin:0 0 12px 0;font-size:1.1em;color:#333;';
heading.textContent = 'Recommended Self-Help';
block.appendChild(heading);

var list = document.createElement('ul');
list.style.cssText = 'margin:0;padding-left:20px;list-style:disc;';

// Collect sidebar links (non-current articles)
var sidebarItems = document.querySelectorAll('.sidenav-item:not(.current-article)');
for (var i = 0; i < sidebarItems.length; i++) {
    (function(link) {
        var li = document.createElement('li');
        li.style.marginBottom = '6px';
        var a = document.createElement('a');
        a.href = link.getAttribute('href');
        a.textContent = link.textContent.trim();
        a.style.color = '#520044';
        li.appendChild(a);
        list.appendChild(li);
    })(sidebarItems[i]);
}

// Collect related articles links
var relatedLinks = document.querySelectorAll('.related-articles ul li a');
for (var j = 0; j < relatedLinks.length; j++) {
    (function(link) {
        var existingTexts = [];
        var existingLis = list.querySelectorAll('li a');
        for (var k = 0; k < existingLis.length; k++) {
            existingTexts.push(existingLis[k].textContent.trim());
        }
        var text = link.textContent.trim();
        if (existingTexts.indexOf(text) === -1) {
            var li2 = document.createElement('li');
            li2.style.marginBottom = '6px';
            var a2 = document.createElement('a');
            a2.href = link.getAttribute('href');
            a2.textContent = text;
            a2.style.color = '#520044';
            li2.appendChild(a2);
            list.appendChild(li2);
        }
    })(relatedLinks[j]);
}

if (list.children.length > 0) {
    block.appendChild(list);
    element.parentNode.insertBefore(block, element.nextSibling);
}
